/**
 * load-projects.js — homepage script.
 * Fetches site/data/{title,main,projects}.json (generated by
 * scripts/build.py) and renders the hero (incl. optional highlight
 * bullets from data/main.yaml), the about text, and the project grid
 * — now rendered as one section per category (data/projects/<category>/),
 * in the order configured by data/main.yaml's project_categories.order.
 * No hand-editing of HTML needed to add a project or a category — just
 * add/edit a YAML file and rebuild.
 */
(function () {
  async function fetchJSON(path) {
    const res = await fetch(path);
    if (!res.ok) throw new Error('Failed to fetch ' + path);
    return res.json();
  }

  // main.json is optional — a repo that hasn't added data/main.yaml yet
  // should still render fine with sensible fallbacks.
  async function fetchJSONOptional(path) {
    try {
      return await fetchJSON(path);
    } catch (err) {
      return null;
    }
  }

  function el(tag, className, html) {
    const e = document.createElement(tag);
    if (className) e.className = className;
    if (html !== undefined) e.innerHTML = html;
    return e;
  }

  function renderHero(title, main) {
    const nameEl = document.querySelector('[data-hero-name]');
    const taglineEl = document.querySelector('[data-hero-tagline]');
    const ledeEl = document.querySelector('[data-hero-lede]');
    const linksEl = document.querySelector('[data-hero-links]');
    const highlightsEl = document.querySelector('[data-hero-highlights]');

    if (nameEl) nameEl.textContent = title.name;
    if (taglineEl) taglineEl.textContent = title.tagline;

    if (ledeEl) {
      const fallbackLede = title.location ? `Based in ${title.location}.` : '';
      ledeEl.textContent = (main && main.hero_lede) ? main.hero_lede : fallbackLede;
    }

    // Optional small bullet points (data/main.yaml `highlights:`). Only
    // shown when the list is non-empty, so leaving it out (or empty)
    // in main.yaml simply skips this section with no leftover gap.
    if (highlightsEl) {
      highlightsEl.innerHTML = '';
      const items = (main && Array.isArray(main.highlights)) ? main.highlights : [];
      if (items.length) {
        items.forEach((h) => highlightsEl.appendChild(el('li', null, h)));
        highlightsEl.hidden = false;
      } else {
        highlightsEl.hidden = true;
      }
    }

    if (linksEl) {
      linksEl.innerHTML = '';
      const entries = [
        ['Email', 'mailto:' + title.email],
        ['GitHub', title.links && title.links.github],
        ['LinkedIn', title.links && title.links.linkedin],
        ['Resume (PDF)', title.resume_pdf],
      ];
      entries.forEach(([label, href]) => {
        if (!href) return;
        const a = el('a', null, label);
        a.href = href;
        linksEl.appendChild(a);
      });
    }
    document.title = `${title.name} — ${title.tagline}`;
  }

  function renderAbout(main) {
    const aboutEl = document.querySelector('[data-about-text]');
    if (aboutEl && main && main.about_text) {
      aboutEl.textContent = main.about_text;
    }
  }

  function renderCard(project) {
    const card = el('article', 'project-card');

    const thumb = el('div', 'thumb');
    if (project.preview_image && project.preview_image.src) {
      const img = el('img');
      img.src = project.preview_image.src;
      img.alt = project.preview_image.title || project.title;
      img.loading = 'lazy';
      thumb.appendChild(img);
    }
    card.appendChild(thumb);

    const body = el('div', 'body');
    body.appendChild(el('h3', null, project.title));
    if (project.dates) body.appendChild(el('div', 'meta', project.dates));
    body.appendChild(el('p', null, project.short_description));

    if (project.tags && project.tags.length) {
      const tagsWrap = el('div', 'tags');
      project.tags.forEach((t) => tagsWrap.appendChild(el('span', 'tag', t)));
      body.appendChild(tagsWrap);
    }
    card.appendChild(body);

    const link = el('a');
    link.href = `project.html?slug=${encodeURIComponent(project.slug)}`;
    link.style.display = 'contents';
    link.setAttribute('aria-label', `View project: ${project.title}`);
    link.appendChild(card);
    return link;
  }

  // projects.json is now a list of category groups:
  //   [{ slug, label, projects: [...] }, ...]
  // Each non-empty category renders as its own heading + grid, in the
  // order the build script already sorted them into.
  function renderCategory(category) {
    const section = el('div', 'project-category');
    section.appendChild(el('h3', 'category-heading', category.label));
    const grid = el('div', 'project-grid');
    category.projects.forEach((p) => grid.appendChild(renderCard(p)));
    section.appendChild(grid);
    return section;
  }

  async function main() {
    const grid = document.querySelector('[data-project-grid]');
    try {
      const [title, mainCfg, categories] = await Promise.all([
        fetchJSON('data/title.json'),
        fetchJSONOptional('data/main.json'),
        fetchJSON('data/projects.json'),
      ]);
      renderHero(title, mainCfg);
      renderAbout(mainCfg);
      if (grid) {
        grid.innerHTML = '';
        categories.forEach((cat) => {
          if (!cat.projects || !cat.projects.length) return;
          grid.appendChild(renderCategory(cat));
        });
      }
    } catch (err) {
      console.error(err);
      if (grid) grid.innerHTML = '<p style="color:#7C8894">Could not load project data.</p>';
    }
  }

  main();
})();
